<script setup lang="ts">
import {UserRound,Save,ShieldCheck} from 'lucide-vue-next'
import type {Profile} from '~/types/models'
import { phoneIssue, emailIssue } from '~/shared/identity-validation'
const {data:auth}=await useFetch<{authenticated:boolean;authMethod?:string;vneid?:boolean}>('/api/auth/me',{key:'citizen-auth-profile'})
const {data:profile,error,refresh}=await useFetch<Profile>('/api/profile', {key:'citizen-profile'})
const form=reactive({display_name:'',email:'',phone:'',address:''})
const editing=ref(false)
watch(profile,(v)=>{if(v&&!editing.value){form.display_name=v.display_name;form.email=v.email;form.phone=v.phone;form.address=v.address}},{immediate:true})
const busy=ref(false);const result=ref('');const success=ref(false)
const invalidPhone=computed(()=>phoneIssue(form.phone))
const invalidEmail=computed(()=>emailIssue(form.email))
async function save(){result.value='';success.value=false;if(invalidPhone.value||invalidEmail.value){result.value=invalidPhone.value||invalidEmail.value;return}busy.value=true;try{await $fetch('/api/profile',{method:'PATCH',body:form});result.value='Thông tin đã được cập nhật. Số điện thoại và email mới chỉ được kiểm tra định dạng, chưa xác minh sở hữu.';success.value=true;editing.value=false;await refresh();await refreshNuxtData('citizen-auth')}catch(e){result.value=readableError(e)}finally{busy.value=false}}
</script>
<template><div class="space-y-4"><div><h2 class="text-xl font-black">Hồ sơ cá nhân</h2><p class="text-sm text-muted">Quản lý thông tin tài khoản Công dân đang đăng nhập.</p></div><div v-if="error" class="panel p-6 text-rose-700">Không tải được hồ sơ cá nhân.</div><form v-else class="panel space-y-5 p-5" @submit.prevent="save" @input="editing=true"><div class="flex items-center gap-3 border-b pb-4"><span class="grid h-16 w-16 place-items-center rounded-full bg-brand-100 text-brand-600"><UserRound :size="35"/></span><div><b class="text-lg">{{profile?.display_name}}</b><p class="text-sm text-muted">Công dân · {{profile?.tenant_name}}</p><p class="mt-1 text-xs text-brand-700">{{auth?.vneid?'Đăng nhập qua định danh VNeID được cấu hình':auth?.authMethod==='oidc'?'Đăng nhập qua hệ thống định danh OIDC':'Tài khoản công dân demo / nội bộ'}}</p></div></div><div class="grid gap-4 sm:grid-cols-2"><div><label for="profile-name" class="field-label">Họ và tên</label><input id="profile-name" v-model="form.display_name" class="field" required minlength="2" maxlength="100"/></div><div><label for="profile-email" class="field-label">Email</label><input id="profile-email" v-model="form.email" class="field" type="email" maxlength="150" autocomplete="email" :aria-invalid="Boolean(invalidEmail)" aria-describedby="profile-email-error"/><p id="profile-email-error" v-if="invalidEmail" role="alert" class="text-xs text-rose-700">{{invalidEmail}}</p></div><div><label for="profile-phone" class="field-label">Số điện thoại</label><input id="profile-phone" v-model="form.phone" class="field" maxlength="25" type="tel" autocomplete="tel" :aria-invalid="Boolean(invalidPhone)" aria-describedby="profile-phone-error"/><p id="profile-phone-error" v-if="invalidPhone" role="alert" class="text-xs text-rose-700">{{invalidPhone}}</p></div><div><label for="profile-address" class="field-label">Địa chỉ</label><input id="profile-address" v-model="form.address" class="field" maxlength="250"/></div></div><p v-if="result" :class="success ? 'rounded-lg bg-green-50 p-3 text-sm text-green-800' : 'rounded-lg bg-rose-50 p-3 text-sm text-rose-800'" role="status">{{result}}</p><p class="text-xs text-muted">Kiểm tra định dạng không có nghĩa là số điện thoại, email hay danh tính đã được xác minh.</p><div class="flex flex-wrap items-center justify-between gap-3 border-t pt-4"><NuxtLink to="/bao-mat" class="btn-outline"><ShieldCheck :size="17"/> Bảo mật tài khoản</NuxtLink><button class="btn-primary" :disabled="busy||!!invalidPhone||!!invalidEmail" type="submit"><Save :size="17"/>{{busy?'Đang lưu...':'Lưu thay đổi'}}</button></div></form><CitizenPreferencesPanel/></div></template>
